window.ScripturaLexicons.BDAG_PART_0241 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-01\" data-source=\"BDAG\" data-search=\"μῦς, μυός, ὁ substantivo masculino rato; camundongo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μῦς, μυός, ὁ</td><td>substantivo masculino</td><td>rato; camundongo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-02\" data-source=\"BDAG\" data-search=\"μυσερός, ά, όν adjetivo repugnante; abominável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μυσερός, ά, όν</td><td>adjetivo</td><td>repugnante; abominável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-03\" data-source=\"BDAG\" data-search=\"Μυσία, ας, ἡ nome próprio feminino Mísia, província da Ásia Menor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μυσία, ας, ἡ</td><td>nome próprio feminino</td><td>Mísia, província da Ásia Menor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-04\" data-source=\"BDAG\" data-search=\"μυστήριον, ου, τό substantivo neutro mistério; segredo; desígnio de Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μυστήριον, ου, τό</td><td>substantivo neutro</td><td>mistério; segredo; desígnio de Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-05\" data-source=\"BDAG\" data-search=\"Μυτιλήνη remissão nominal ver Μιτυλήνη BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μυτιλήνη</td><td>remissão nominal</td><td>ver Μιτυλήνη</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-06\" data-source=\"BDAG\" data-search=\"μυωπάζω verbo ser míope, figuradamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μυωπάζω</td><td>verbo</td><td>ser míope, figuradamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-07\" data-source=\"BDAG\" data-search=\"Μωδάτ, ὁ nome próprio masculino Modade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μωδάτ, ὁ</td><td>nome próprio masculino</td><td>Modade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-08\" data-source=\"BDAG\" data-search=\"μώλωψ, ωπος ὁ substantivo masculino vergão; ferida de pancada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μώλωψ, ωπος ὁ</td><td>substantivo masculino</td><td>vergão; ferida de pancada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-09\" data-source=\"BDAG\" data-search=\"μωμάομαι verbo médio criticar; censurar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωμάομαι</td><td>verbo médio</td><td>criticar; censurar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-10\" data-source=\"BDAG\" data-search=\"μῶμος, ου, ὁ substantivo masculino censura; defeito; mácula BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μῶμος, ου, ὁ</td><td>substantivo masculino</td><td>censura; defeito; mácula</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-11\" data-source=\"BDAG\" data-search=\"μωμοσκοπέομαι verbo médio examinar à procura de defeitos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωμοσκοπέομαι</td><td>verbo médio</td><td>examinar à procura de defeitos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-12\" data-source=\"BDAG\" data-search=\"μωραίνω verbo tornar tolo; tornar insípido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωραίνω</td><td>verbo</td><td>tornar tolo; tornar insípido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-13\" data-source=\"BDAG\" data-search=\"μωρία, ας, ἡ substantivo feminino loucura; insensatez BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωρία, ας, ἡ</td><td>substantivo feminino</td><td>loucura; insensatez</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-14\" data-source=\"BDAG\" data-search=\"μωρολογία, ας, ἡ substantivo feminino palavreado tolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωρολογία, ας, ἡ</td><td>substantivo feminino</td><td>palavreado tolo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-15\" data-source=\"BDAG\" data-search=\"μωρός, ά, όν adjetivo tolo; estúpido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωρός, ά, όν</td><td>adjetivo</td><td>tolo; estúpido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-16\" data-source=\"BDAG\" data-search=\"μωρῶς advérbio insensatamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μωρῶς</td><td>advérbio</td><td>insensatamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-17\" data-source=\"BDAG\" data-search=\"Μωσῆς remissão nominal ver Μωϋσῆς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μωσῆς</td><td>remissão nominal</td><td>ver Μωϋσῆς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-18\" data-source=\"BDAG\" data-search=\"Μωϋσῆς nome próprio masculino Moisés; legislador hebreu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μωϋσῆς</td><td>nome próprio masculino</td><td>Moisés; legislador hebreu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-19\" data-source=\"BDAG\" data-search=\"Ναασσών, ὁ nome próprio masculino Naassom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ναασσών, ὁ</td><td>nome próprio masculino</td><td>Naassom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0241-20\" data-source=\"BDAG\" data-search=\"Νάβαλ, ὁ nome próprio masculino Nabal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Νάβαλ, ὁ</td><td>nome próprio masculino</td><td>Nabal</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0241-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῦς, μυός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μῦς</span>, <span class=\"greek\">μυός</span>, <span class=\"greek\">ὁ</span> (Aeschyl. e outros; papiros; Lev 11:29), acusativo plural <span class=\"greek\">μῦς</span> (Hdt. 2, 141; Plut., Mor. 537a; Just., A I, 24, 1), camundongo, rato PtK 2 p. 14, 19.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυσερός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μυσερός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">μύσος</span>, “contaminação”; como <span class=\"greek\">μυσαρός</span> em Eur., Hdt. e outros; Ins. aus d, Asklepieion v. Kos A, 22 [III a.C.]: RHerzog, ARW 10, 1907, 402; SibOr 3, 500. Sobre a grafia, ver B-D-F §29, 1. Na LXX, somente em Lev 18:23, onde <span class=\"greek\">μυσερός</span> é mais bem atestado; ver Thackeray 75.—PGM 2, 148 <span class=\"greek\">ἁγνὸς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">μυσεροῦ</span>; Manetho, Apotel. 4, 269 <span class=\"greek\">μυσερός</span> é variante de leitura; Etym. Mag. 535, 32; 566, 43 <span class=\"greek\">μυσε</span>. ao lado de <span class=\"greek\">μυσα</span>.; Malalas [VI d.C.] <span class=\"greek\">μυσε</span>. [Psaltes p. 2]), repugnante, abominável, detestável: <span class=\"greek\">ζῆλος</span> 1 Cl 14:1. <span class=\"greek\">μοιχεία</span> 30:1.—DELG s.v. <span class=\"greek\">μύσος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυσία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μυσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Eur., Hdt. e outros; inscrições; Jos., Bell. 1, 425), Mísia, província no noroeste da Ásia Menor. Paulo passou por essa região em sua assim chamada segunda viagem missionária Ac 16:7f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυστήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μυστήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span>, “segredo, rito secreto, ensinamento secreto, mistério”; termo técnico religioso (predominantemente no plural), aplicado no mundo greco-romano sobretudo aos mistérios, com seus ensinamentos secretos, de natureza religiosa e política, ocultos em numerosos costumes e cerimônias insólitos. Os ritos principais permanecem desconhecidos por causa da relutância dos antigos em revelá-los (trágicos e posteriores; Hdt. 2, 51, 2; Diod S 1, 29, 3; 3, 63, 2; Socrat., Ep. 27, 3; Cornutus 28 p. 56, 22; 57, 4; Alciphron 3, 26, 1; OGI 331, 54; 528, 13; 721, 2, SIG, ver índice; Sb 7567, 9 [III d.C.]; PGM 1, 131; 4, 719ff; 2477 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">γνῶσιν</span>; 5, 110; 12, 331; 13, 128 <span class=\"greek\">τὸ</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>. Somente o gnóstico perfeito é <span class=\"greek\">τῶν</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">ἀκροατής</span> Hippol., Ref. 5, 8, 29.—OKern, D. griech. Mysterien d. klass. Zeit 1927; WOtto, D. Sinn der eleusin. Myst. ’40; MNilsson, The Dionysiac Mysteries of the Hell. and Rom. Age, ’57; Kl. Pauly III 1533–42; WBurkert, Antike Mysterien ’90). Também a LXX e outras versões do AT empregam a palavra, assim como En (do segredo celeste) e numerosos escritos pseudoepígrafos, Philo, Joseph. (C. Ap. 2, 189, 266), apologistas (exceto Ar.); é empréstimo no rabínico. Nossa literatura emprega <span class=\"greek\">μ</span>. com referência à atividade transcendente de Deus e ao efeito dela sobre o povo de Deus.</p><p class=\"entry-text\">① O desígnio ainda não manifestado ou reservado de Deus, segredo (de Deus), pensamentos, planos e disposições secretos de Deus (SJCh 78, 9; <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μοναρχίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> Theoph. Ant. 2, 28 [p. 166, 17]), ocultos à razão humana, bem como a toda outra compreensão inferior à esfera divina, e que aguardam seu cumprimento ou sua revelação aos seus destinatários (o Logos divino como <span class=\"greek\">διδάσκαλος</span> <span class=\"greek\">θείων</span> <span class=\"greek\">μυστηρίων</span> Orig., C. Cels. 3, 62, 9; as constelações como <span class=\"greek\">δεῖγμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τύπον</span> … <span class=\"greek\">μεγάλου</span> <span class=\"greek\">μυστηρίου</span> Hippol. Ant. 2, 15 [p. 138, 7]; Abraão é <span class=\"greek\">τῶν</span> <span class=\"greek\">θείων</span> … <span class=\"greek\">μέτοχος</span> <span class=\"greek\">μυστηρίων</span> Did., Gen. 213, 20).</p><p class=\"entry-text\">ⓐ Nos evangelhos, <span class=\"greek\">μ</span>. ocorre apenas num contexto, quando Jesus diz aos discípulos que lhe pediram uma explicação da parábola ou das parábolas: <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">δέδοται</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:11</a>; os paralelos sinóticos trazem o plural <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:11</a> (LCerfaux, NTS 2, ’55/56, 238–49); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:10</a>.—WWrede, D. Messiasgeh. in den Evv. 1901; HEbeling, D. Messiasgeh. u. d. Botschaft des Mc-Evangelisten ’39; NJohansson, SvTK 16, ’40, 3–38; OPiper, Interpretation 1, ’47, 183–200; RArida, St Vladimar Theol. Qtly 38, ’94, 211–34 (exegese patrística de Mk 4:10–12 e paralelos).</p><p class=\"entry-text\">ⓑ A literatura paulina apresenta <span class=\"greek\">μ</span>. em 21 passagens. Um segredo ou mistério profundo demais para a engenhosidade humana é a razão divina do endurecimento parcial do coração de Israel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>, ou da transformação dos cristãos sobreviventes na parúsia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.51\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:51</a>. Até o próprio Cristo, compreendido por tão poucos, é o segredo ou mistério de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a>, oculto desde eras passadas 1:26 (cf. Herm. Wr. 1, 16 <span class=\"greek\">τοῦτό</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκρυμμένον</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">τῆσδε</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>), mas agora revelado gloriosamente entre os gentios, versículo 27, aos quais é proclamado o segredo de Cristo, isto é, sua relevância para eles, 4:3 (CMitton, ET 60, ’48/49, 320f). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:1</a> (cf. Just., D. 91, 1; 131, 2 e outros <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>; 74, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">σωτήριον</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μ</span>., <span class=\"greek\">τοῦτ</span>’ <span class=\"greek\">ἔστι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστοῦ</span>). O plural é empregado para designar a pregação cristã pelos apóstolos e mestres na expressão <span class=\"greek\">οἰκονόμοι</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:1</a> (Iambl., Vi. Pyth. 23, 104 denomina os ensinamentos de Pitágoras <span class=\"greek\">θεῖα</span> <span class=\"greek\">μυστήρια</span>). Nem todos os cristãos são capazes de compreender todos os mistérios. Quem fala em línguas <span class=\"greek\">πνεύματι</span> <span class=\"greek\">λαλεῖ</span> <span class=\"greek\">μυστήρια</span>, profere verdades secretas no Espírito que somente essa pessoa compartilha com Deus e que outros, mesmo cristãos, não compreendem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:2</a>. Por isso, a posse de todos os mistérios é uma grande alegria 13:2 (Just., D. 44, 2). E o apóstolo cheio do Espírito pode dizer sobre a etapa mais elevada do conhecimento cristão, revelada somente aos <span class=\"greek\">τέλειοι</span>: <span class=\"greek\">λαλοῦμεν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σοφίαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span>, comunicamos a sabedoria de Deus na forma de mistério (<span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span> = de maneira misteriosa [Laud. Therap. 11] ou = secretamente, para que nenhum não autorizado dela tome conhecimento [cf. Cyr. of Scyth. p. 90, 14 <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span> <span class=\"greek\">λέγει</span>]) 2:7 (AKlöpper, ZWT 47, 1905, 525–45).—Efésios, para a qual (assim como para Colossenses) <span class=\"greek\">μ</span>. é conceito predominante, identifica o <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θελήματος</span> <span class=\"greek\">αὐτοῦ</span> (subentenda-se <span class=\"greek\">θεοῦ</span>) 1:9, ou <span class=\"greek\">μ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστοῦ</span> 3:4, ou <span class=\"greek\">μ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">εὐαγγελίου</span> 6:19, na aceitação dos gentios como cristãos 3:3ff, 9ff. Um grande mistério singular é revelado em 5:32, no qual a relação entre Cristo e a comunidade cristã ou igreja é tratada com base em Gen 2:24 (cf. a interpretação do sol como símbolo de Deus, Theoph. Ant. 2, 15 [p. 138, 8], e ver WKnox, St. Paul and the Church of the Gentiles, ’39, 183f; 227f; WBieder, TZ 11, ’55, 329–43).</p><p class=\"entry-text\">ⓒ Em Rv, <span class=\"greek\">μ</span>. é empregado com referência às coisas misteriosas ali retratadas. Todo o conteúdo do livro aparece como <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 10:7. Também <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἀστέρων</span> 1:20; <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικός</span> 17:7, cf. versículo 5, caso em que <span class=\"greek\">μ</span>. pode significar, em cada ocorrência, sentido alegórico (assim BEaston, Pastoral Epistles ’47, 215).</p><p class=\"entry-text\">② Aquilo que transcende a compreensão comum, realidade transcendente ou última, segredo, com ênfase na experiência israelita/cristã.</p><p class=\"entry-text\">ⓐ 1 Ti emprega <span class=\"greek\">μ</span>. como fórmula: <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> é simplesmente a fé 3:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐσεβείας</span> <span class=\"greek\">μ</span>., o segredo da (nossa) piedade, versículo 16.—<span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνομίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:7</a>, ver <span class=\"greek\">ἀνομία</span> 1 (Jos., Bell. 1, 470 chama a vida de Antípatro <span class=\"greek\">κακίας</span> <span class=\"greek\">μυστήριον</span>, em razão de sua vileza praticada em segredo. Cf. também SibOr 8, 58 <span class=\"greek\">τὰ</span> <span class=\"greek\">πλάνης</span> <span class=\"greek\">μυστήρια</span>; 56).—PFurfey, CBQ 8, ’46, 179–91.</p><p class=\"entry-text\">ⓑ Em Inácio: a morte e a ressurreição de Jesus como <span class=\"greek\">μ</span>. IMg 9:1 (<span class=\"greek\">τὸ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναστάσεως</span> <span class=\"greek\">μ</span>. Orig., C. Cels. 1, 7, 9). A virgindade de Maria, seu parto e a morte do Senhor são denominados <span class=\"greek\">τρία</span> <span class=\"greek\">μ</span>. <span class=\"greek\">κραυγῆς</span>, três mistérios (para serem) proclamados em alta voz IEph 19:1 (são mistérios porque contrariam de modo tão radical a expectativa humana). Também da anunciação a Maria e de sua concepção GJs 12:2f. Os diáconos são <span class=\"greek\">οἱ</span> <span class=\"greek\">διάκονοι</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. ITr 2:3.</p><p class=\"entry-text\">ⓒ Bastante difícil é a declaração sobre o profeta provado e digno de confiança <span class=\"greek\">ποιῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">κοσμικὸν</span> <span class=\"greek\">ἐκκλησίας</span>, aquele que age de acordo com o mistério terreno da assembleia (de Deus) D 11:11. Pode referir-se ao celibato; o profeta vive de maneira correspondente à relação entre Cristo e o povo de Deus; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:32</a> (assim Harnack, TU II 1; 2, 1884, 44ff; HWeinel, Die Wirkungen d. Geistes u. der Geister 1899, 131–38; PDrews, Hdb. z. d. ntl. Apokryphen 1904, 274ff; RKnopf, Hdb. ad loc.—Diferentemente CTaylor, The Teaching of the Twelve Apost. 1886, 82–92; RHarris, The Teaching of the Ap. 1887; FFunk, Patr. Apostol.2 1901 ad loc.; Zahn, Forschungen III 1884, 301).</p><p class=\"entry-text\">ⓓ <span class=\"greek\">μ</span>. ocorre com frequência em Dg: <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοσεβείας</span> <span class=\"greek\">μ</span>., o segredo da (nossa) piedade 4:6 (o sentido de <span class=\"greek\">μ</span>. em Dg é exposto detalhadamente no capítulo 5). De modo semelhante, a respeito do ensinamento cristão (cf. Ps.-Phocyl. 229 e comentários de Horst 260–61), <span class=\"greek\">πατρὸς</span> <span class=\"greek\">μυστήρια</span> 11:2; cf. versículo 5. Assim, o cristão pode <span class=\"greek\">μυστήρια</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λαλεῖν</span> 10:7. Em contraste com <span class=\"greek\">ἀνθρώπινα</span> <span class=\"greek\">μ</span>. 7:1. <span class=\"greek\">οὗ</span> (subentenda-se <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">μυστήρια</span>, cujos desígnios secretos 7:2 (a vontade divina para o governo ordenado do universo). De Deus que reserva para si seu plano: <span class=\"greek\">κατεῖχεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μυστηρίῳ</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">σοφὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">βουλήν</span> 8:10.—Lghtf., St. Paul’s Ep. to the Col. and Phlm. p. 167ff; JRobinson, St. Paul’s Ep. to the Eph. 1904, 234ff; GWobbermin, Religionsgesch. Studien 1896, 144ff; EHatch, Essays on Bibl. Gk. 1889, 57ff; HvSoden, ZNW 12, 1911, 188ff; TFoster, AJT 19, 1915, 402–15; OCasel, D. Liturgie als Mysterienfeier5 1923; JSchneider, ‘Mysterion’ im NT: StKr 104, ’32, 255–78; TArvedson, D. Mysterium Christi ’37; KPrümm, ‘Mysterion’ v. Pls bis Orig.: ZKT 61, ’37, 391–425, Biblica 37, ’56, 135–61; RBrown, The Semitic Background of ‘Mystery’ in the NT, ’68; cf. KKuhn, NTS 7, 61, 366 para paralelos de Qumran com diversas passagens de Eph e Ro; ABöhlig, Mysterion u. Wahrheit, ’68, 3–40; JFruytier, Het woord M. in de catechesen van Cyrillus van Jerusalem, ’50; ANock, Hellenistic Mysteries and Christian Sacraments, Essays on Religion and the Ancient World II, ’72, 790–820; AHarvey, The Use of Mystery Language in the Bible: JTS 31, ’80, 320–36.—DELG s.v. <span class=\"greek\">μύω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μυτιλήνη</h1><div class=\"entry-meta\"><span>remissão nominal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μυτιλήνη</span>, ver <span class=\"greek\">Μιτυλήνη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μυωπάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μυωπάζω</span> (<span class=\"greek\">μύωψ</span> [<span class=\"greek\">μύω</span>, “fechar” os olhos, <span class=\"greek\">ὤψ</span>, “olho”], “fechar ou contrair os olhos” = semicerrar os olhos, como fazem os míopes), somente em escritores cristãos: Basilius 2, 825b [MPG XXX]; Epiph. 59, 11, 1 Holl; Ps.-Dionys., Eccl. Hierarch. 2, 3, 3), ser míope, figuradamente: <span class=\"greek\">τυφλός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μυωπάζων</span>, ele é tão míope que está cego <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a> (em oposição a <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">ἐπίγνωσις</span>; JMayor, Comm. ad loc.).—DELG s.v. <span class=\"greek\">μύω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μωδάτ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μωδάτ</span>, <span class=\"greek\">ὁ</span>, indeclinável, Modade Hv 2, 3, 4; ver o verbete <span class=\"greek\">Ἐλδάδ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μώλωψ, ωπος ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μώλωψ</span>, <span class=\"greek\">ωπος</span> <span class=\"greek\">ὁ</span> (Hyperid., Fgm. 200; Plut., Mor. 565b; Herodian Gr. I 247, 20; LXX), vergão, equimose, contusão, ferida causada por pancadas (Machon, versículo 285; Dionys. Hal. 16, 5, 2; Pausanias Attic. <span class=\"greek\">ζ</span>, 5 <span class=\"greek\">μώλωψ</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πληγῆς</span> <span class=\"greek\">οἴδημα</span>, “inchaço causado por uma pancada”; Artem. 2, 48 p. 150, 4; Lucian, Philops. 20, de vergões causados por açoites; Sir 28:17) <span class=\"greek\">οὗ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μώλωπι</span> <span class=\"greek\">ἰάθητε</span>, por seu vergão ou por suas feridas fostes curados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:24</a>; cf. 1 Cl 16:5; 5:2 (todas as passagens remetem a Is 53:5; essa passagem revista em Just., D. 17, 1 <span class=\"greek\">δἰ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μωλώπων</span> <span class=\"greek\">ἴασις</span> <span class=\"greek\">γίνεται</span>; 137, 1 <span class=\"greek\">μηδὲ</span> <span class=\"greek\">χλευάσητε</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μώλωπας</span>).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωμάομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωμάομαι</span> (<span class=\"greek\">μῶμος</span>), depoente médio; futuro na 3ª pessoa singular <span class=\"greek\">μωμήσεται</span> Pr 9:7; 1º aoristo <span class=\"greek\">ἐμωμησάμην</span>. Passivo: aoristo <span class=\"greek\">ἐμωμήθην</span>; particípio perfeito feminino <span class=\"greek\">μεμωμημένη</span> Sir 34:18 (Hom. e outros; Plut., Mor. 346a; LXX; Philo, Leg. All. 3, 180), encontrar defeito em, criticar, censurar, culpar <span class=\"greek\">τινά</span>, alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:20</a>. Passivo: ser objeto de censura 6:3.—DELG s.v. <span class=\"greek\">μῶμος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῶμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μῶμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (ver o verbete precedente; sobre a etimologia, ver LfgrE s.v.).</p><p class=\"entry-text\">① Censura (Hom. e outros; Kaibel 948, 8; Sir 18:15; SibOr 3, 377) <span class=\"greek\">δίχα</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">μ</span>., sem qualquer censura 1 Cl 63:1.</p><p class=\"entry-text\">② Defeito, mácula, mancha, corporal (Lev 21:17f, 21; 24:19f; TestLevi 9:10) e também moral (Sir 11:31, 33; 20:24; Philo, Sobr. 11 <span class=\"greek\">μ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ψυχῇ</span>); de mestres dissidentes <span class=\"greek\">σπίλοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μῶμοι</span>, manchas e defeitos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:13</a>.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωμοσκοπέομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωμοσκοπέομαι</span> (<span class=\"greek\">μῶμος</span>, <span class=\"greek\">σκοπέω</span>), depoente médio; particípio do 1º aoristo passivo <span class=\"greek\">μωμοσκοπηθείς</span> (Const. Apost. 2, 3; o substantivo <span class=\"greek\">μωμοσκόπος</span> em Philo, Agr. 130; Clem. Al., Strom. 4, 18, 117), examinar à procura de defeitos.</p><p class=\"entry-text\">ⓐ Termo técnico do uso sacrificial: de animal sacrificial etc. 1 Cl 41:2.</p><p class=\"entry-text\">ⓑ Figuradamente, de Deus, que <span class=\"greek\">πάντα</span> <span class=\"greek\">μωμοσκοπεῖται</span>, examina tudo (à procura de defeitos) Pol 4:3.—Cf. DELG s.v. <span class=\"greek\">σκέπτομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωραίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωραίνω</span> (<span class=\"greek\">μωρός</span>), 1º aoristo <span class=\"greek\">ἐμώρανα</span>. Passivo: futuro na 3ª pessoa singular <span class=\"greek\">μωρανθήσεται</span> Is 19:11; 1º aoristo <span class=\"greek\">ἐμωράνθην</span> (Eur. e outros, mas intransitivo; também Philo, Cher. 116), em nossa literatura somente transitivo (Polemo, Decl. 2, 36; LXX; intransitivo em Just., D. 67, 2; Tat. 21, 1).</p><p class=\"entry-text\">① Tornar tolo, mostrar que é tolo: <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">ἐμώρανεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σοφίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>;, Deus não demonstrou que a sabedoria do mundo é loucura? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:20</a>. Passivo com sentido ativo, tornar-se tolo (Sir 23:14) <span class=\"greek\">φάσκοντες</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">σοφοὶ</span> <span class=\"greek\">ἐμωράνθησαν</span>, embora afirmassem ser sábios, tornaram-se tolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:22</a> (cf. Jer 10:14; Ar. 8, 2).</p><p class=\"entry-text\">② Tornar insípido; passivo, tornar-se insípido, sem sabor, do sal (ver <span class=\"greek\">ἄναλος</span> e FPerles, REJ 82, 1926, 122f; MBlack, Aramaic Approach3, ’67, 166f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:34</a> (variante de leitura <span class=\"greek\">μαρανθῇ</span>).—Ver <span class=\"greek\">ἅλας</span> a.—DELG s.v. 1 <span class=\"greek\">μωρός</span>. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μωρός</span>; Soph., Hdt. e outros; PBrem 61, 28 [II d.C.]; PCairMasp 4, 6 Biz.; Sir 20:31; 41:15; Philo; Jos., Ant. 17, 209; Iren. 1, 16, 3 [Harv. I, 162, 2]), loucura, insensatez, em sentido geral; da sabedoria mundana (Orig., C. Cels. 7, 47, 9) <span class=\"greek\">μ</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἐστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:19</a>. Inversamente, para todos os que se perdem 1:18, e sobretudo para os gentios, versículo 23, a pregação cristã de um Salvador que morreu na cruz com morte de escravo era <span class=\"greek\">μ</span>. (cf. Theoph. Ant. 2, 1 [p. 94, 7]). Aprouve a Deus salvar os crentes <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μωρίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κηρύγματος</span>, por meio da loucura da pregação, versículo 21. O <span class=\"greek\">ψυχικὸς</span> <span class=\"greek\">ἄνθρ</span>. rejeita as coisas do Espírito como <span class=\"greek\">μ</span>., 2:14. O culto do templo judaico é avaliado como <span class=\"greek\">μ</span>. (em contraste com <span class=\"greek\">θεοσέβεια</span>) Dg 3:3.—WCaspari, Über d. bibl. Begriff der Torheit: NKZ 39, 1928, 668–95.—DELG s.v. 1 <span class=\"greek\">μωρός</span>. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρολογία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωρολογία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μωρός</span>, <span class=\"greek\">λογ</span>[<span class=\"greek\">ε</span>]<span class=\"greek\">ία</span>; Aristot., HA 1, 11; Plut., Mor. 504b; Jos., C. Ap. 2, 115), conversa insensata, palavreado tolo, juntamente com <span class=\"greek\">αἰσχρότης</span> e <span class=\"greek\">εὐτραπελία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:4</a> (cf. 1QS 10:21–24: KKuhn, NTS 7, ’61, 339).—DELG s.v. 1 <span class=\"greek\">μωρός</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (trágicos, X., Pla. e posteriores; papiros, LXX; TestLevi 7:2; ParJer 9:30; Philo; Ar.; Just.; empréstimo no rabínico; sobre o acento ver B-D-F §13; Mlt-H.), tolo, estúpido.</p><p class=\"entry-text\">ⓐ De pessoas (Simonides of Ceos 48, 6f [Diehl], que emprega o termo acerca de seu adversário Cleóbulo; Diod S 10, 22; Epict. 2, 2, 16; 3, 24, 86; com <span class=\"greek\">ἄνους</span> Hippol. Ref. 6, 34, 8; substantivado: Orig., C. Cels. 5, 16, 17; Hippol. Ref. 9, 13, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:22</a> (ver c abaixo); (com <span class=\"greek\">τυφλός</span>) 23:17, 19, variante de leitura; (em oposição a <span class=\"greek\">φρόνιμος</span>) 7:26; 25:2f, 8. O mesmo contraste em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:10</a>, no qual o apóstolo compara ironicamente a si mesmo com os coríntios. (Em oposição a <span class=\"greek\">σοφός</span>, como em Lucian, Epigr. 1; Dt 32:6; Sir 21:26) 3:18. Com <span class=\"greek\">ἀσύνετος</span> (Sir 21:18) Hv 3, 6, 5; Hs 9, 22, 4. Com <span class=\"greek\">ἀσύνετος</span> e outros predicados semelhantes 1 Cl 39:1. Dos excessivamente ambiciosos Hs 8, 7, 4. <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>, aquilo que é considerado tolo no mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:27</a> também se refere a pessoas, e pode fazê-lo porque diz respeito não a indivíduos, mas a um atributo geral (B-D-F §138, 1; 263, 4; Rob. 411; Mussies 124).</p><p class=\"entry-text\">ⓑ De coisas (SibOr 3, 226; <span class=\"greek\">περὶ</span> <span class=\"greek\">τροπολογουμένων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μωρῶν</span> <span class=\"greek\">συγγραμμάτων</span> Orig., C. Cels. 4, 51, 28; Theoph. Ant 2, 12 [p. 130, 14]) <span class=\"greek\">ὀξυχολία</span> Hm 5, 2, 4. <span class=\"greek\">παράδοσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:13</a>, variante de leitura. <span class=\"greek\">ζητήσεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:9</a>. <span class=\"greek\">πράγματα</span> Hm 5, 2, 2. <span class=\"greek\">τρυφαί</span> m 12, 2, 1. <span class=\"greek\">διδαχαί</span> Hs 8, 6, 5. <span class=\"greek\">ἀφροσύνη</span> 9, 22, 2. Do <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἐπίγειον</span> m 11:11.—<span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, a loucura de Deus (no julgamento dos incrédulos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:25</a> (cf. Eur., Hipp. 966 <span class=\"greek\">τὸ</span> <span class=\"greek\">μ</span>. = “loucura”).</p><p class=\"entry-text\">ⓒ O significado de <span class=\"greek\">μωρέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:22</a> é controverso. A maioria dos estudiosos o entende, como faziam as antigas versões siríacas, no sentido de “seu tolo!” (Pla., Leg. 9, 857d e Socrat., Ep. 14, 6 <span class=\"greek\">ὦ</span> <span class=\"greek\">μῶρε</span> [como é acentuado no ático] = “seu tolo!” Igualmente Biogr. p. 179.—Epict. 2, 16, 13; 3, 13, 17 <span class=\"greek\">μωρέ</span>; Philo, Cher. 75 <span class=\"greek\">ὦ</span> <span class=\"greek\">μωρέ</span>), às vezes também com a conotação de pessoa obstinada e ímpia (como <span class=\"hebrew\" dir=\"rtl\">נָבָל</span>; cf. Dt 32:6; Is 32:6; Sir 50:26). Desde HPaulus, Comm.2 1804ff I 671 até FSchulthess, ZNW 21, 1922, 241, e SFeigin, JNES 2, ’43, 195, sustenta-se que seja transliteração de <span class=\"hebrew\" dir=\"rtl\">מוֹרֵה</span>, “rebelde” (Dt 21:18, 20); de acordo com KKöhler, ZNW 19, 1920, 91–95, é simplesmente a tradução grega do decalque <span class=\"greek\">ῥακά</span>; segundo HPernot, Pages choisies des Évang. 1925, 61, que remete ao grego moderno, uma simples exclamação de tom humorístico.—RGuelich, ZNW 64, ’73, 39–52; Field, Notes 3–5; Mlt-H. 152f.—B. 1215. DELG. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μωρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μωρῶς</span>, advérbio de <span class=\"greek\">μωρός</span> (X., An. 7, 6, 21 e outros), insensatamente: <span class=\"greek\">ἀπόλλυσθαι</span>, perecer em sua própria insensatez IEph 17:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μωσῆς</h1><div class=\"entry-meta\"><span>remissão nominal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μωσῆς</span>, ver <span class=\"greek\">Μωϋσῆς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μωϋσῆς</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μωϋσῆς</span> (o hebraico <span class=\"hebrew\" dir=\"rtl\">משֶׁה</span> parece ter sido originalmente escrito dessa forma em grego; Manetho [III a.C.]: 609 Fgm. 72 Jac. [em Jos., C. Ap. 1, 250]; Diod S 1, 94, 2; 34+35 Fgm. 1, 3; Nicol. Dam. [I a.C.]: 90 Fgm. 72 Jac., em Jos., Ant. 1, 95; Numenius of Apamea [II d.C.], em Clem. Al., Strom. 1, 150, 4; LXX, ver Thackeray 163, 3; EpArist 144; TestSol 25:3f; Test12Patr; ParJer 7:20; ApcMos, prólogo; AscIs, Philo, Joseph., Mel.—Com <span class=\"greek\">Μωσῆς</span> em AssMos, ApcEsdr.—Com variante de leitura <span class=\"greek\">Μωσῆς</span>: Just., Tat., Ath.—PGM 13 = 8º Livro de Moisés 3; 21; 343; 383; 730 e outros, apresenta <span class=\"greek\">Μοϋσῆς</span>. A forma <span class=\"greek\">Μωσῆς</span> do texto recebido, também em ISm 5:1, variante de leitura [ver edição Bihlmeyer p. xxxvi e ad loc.]; ApcEsdr 6:12 p. 31, 17 Tdf.; Theoph. Ant. 3, 18 [p. 240, 14], ocorre em Diod S 40, 3, 3; 6; Strabo 16, 2, 35; 39; LXX; Demetr.: 722 Fgm. 2, 1 e outros; Ezk. Trag., versículo 30, em Clem. 1, 155, 5; SibOr. Sobre a grafia, B-D-F §38; 53, 1; W-S. §5, 21e; Mlt-H. 86f; EbNestle, ZAW 27, 1907, 111–13; Preisigke, Namenbuch; Wuthnow 79f), <span class=\"greek\">έως</span>, <span class=\"greek\">ὁ</span> (também Mel., P. 11, 77; ou <span class=\"greek\">Μωϋσῆ</span> com a LXX; AscIs 3:8; <span class=\"greek\">Μωσῆ</span> ApcEsdr 6:12 p. 31, 17 Tdf.); dativo <span class=\"greek\">εῖ</span> e <span class=\"greek\">ῇ</span> (a última forma em todas as edições de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:44</a>, também no texto recebido de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:46</a>; 9:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:15</a>; Mel., P. 69, 502, com variações dos manuscritos); acusativo, na maioria das vezes <span class=\"greek\">ῆν</span> (Demetr. [ver acima]; Ezk. Trag., versículo 30; todas as edições de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:11</a>; 7:35; 1 Cor. 10:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:3</a>); raramente <span class=\"greek\">έα</span> (todas as edições de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:29</a>; também Mel., P. 59, 433; ambas as formas em Just., Tat.); vocativo <span class=\"greek\">ῆ</span> (Ezk. Trag., versículo 243 <span class=\"greek\">Μωσῆ</span>) 4:8; 1 Cl 53:2, variante de leitura. Sobre a declinação, ver B-D-F §55, 1d; Mlt-H. 146; W-S. §10, 5 e nota 4. Moisés, irmão de Miriã (ver Ex 15:20; Mi 6:4), legislador dos hebreus (como tal em Manetho: 609, Fgm. 10, 250 Jac. [em Jos., C. Ap. 1, 250], sem ser nomeado, mas como autor de Gen 1:3, 9f; assim também <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 9, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:4</a>; 19:7f; 22:24 (fórmula introdutória bastante comum <span class=\"greek\">Μ</span>. <span class=\"greek\">εἶπεν</span>, seguida por Dt 25:5, como em Epict. 1, 28, 4 <span class=\"greek\">ὡς</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">Πλάτων</span> [Sophista 228c]; Just., D. 20, 1; 126, 4 <span class=\"greek\">Μ</span>. <span class=\"greek\">φησιν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; 7:10; 10:3f; 12:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a>; 20:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:17</a>; 7:19, 22f; 8:5. Pormenores da história de sua vida: resumo de sua vida Ac 7:20ff.; Hb 11:23f. Sua fuga 1 Cl 4:10. A teofania na sarça ardente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:37</a>. A serpente levantada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:14</a>. A concessão do maná 6:32. A conversa de Moisés com Deus 9:29, permanência no Sinai 1 Cl 53:2; B 4:7; 14:2ff; 15:1, rosto resplandecente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a> (cf. Ex 34:29ff), um véu sobre ele, versículo 13 (cf. Ex 34:33). Janes e Jambres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:8</a>. Datã e Abirão 1 Cl 4:12. A disputa entre Miguel e o diabo pelo cadáver de Moisés Jd 9. <span class=\"greek\">πιστὸς</span> <span class=\"greek\">θεράπων</span> 1 Cl 43:1 (cf. Num 12:7); cf. 17:5; 51:3, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:5</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">δοῦλος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:3</a>. Designado <span class=\"greek\">προφήτης</span> (Philo; Jos., Ant. 4, 329; Just., A I, 32, 1 e outros; PGM 5, 109 <span class=\"greek\">ἐγώ</span> <span class=\"greek\">εἰμι</span> <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">σου</span>, <span class=\"greek\">ᾧ</span> <span class=\"greek\">παρέδωκας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μυστήριά</span> <span class=\"greek\">σου</span>) 6:8. <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ἐλάλησεν</span> 10:2, 9; cf. 12:2 (Just., D. 49, 7; 91, 4). <span class=\"greek\">ποιεῖ</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> 12:5ff. Com Elias (PDabeck, Biblica 23, ’42, 175–89) Mt 17:3f; Mk 9:4f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:30</a>, 33. Moisés = os livros de Moisés (como em Plut., Mor. 379a, Platão = escritos de Pla.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:15</a>. Correspondentemente, Moisés e os profetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:29</a>, 31; 24:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:22</a>. Cf. ISm 5:1.—Bibliografia sobre Moisés na Hagadá: Monats-schr. f. Gesch. u. Wiss. d. Judent. 77, ’33, 390–92.—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ναασσών, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ναασσών</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">נַחְשׁוֹן</span> Ex 6:23 [citado por Philo, Poster. Cai. 76]; Num 1:7; Ruth 4:20), Naassom, na genealogia de Jesus Mt 1:4ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:32</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0241-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νάβαλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Νάβαλ</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\" dir=\"rtl\">נָבָל</span>; <span class=\"greek\">Ναβαλ</span> LXX; <span class=\"greek\">Νάβαλος</span> Joseph.), Nabal AcPl Ha 6, 22f (segundo 1 Kgm 25:3ff).</p></section></article>"};
